import type { BiomarkerInput, CancerInput, EntityInput, PaperInput, PathwayInput, TargetInput, TechnologyInput, TermInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * LUNG CANCER, MOLECULAR LAYER. Facts checked 25 September 2026.
 *
 * In lung cancer the molecular layer is not background to the treatment layer, it is the treatment layer: a dozen
 * alterations each select a licensed medicine, and the histological label (adenocarcinoma, squamous, small-cell)
 * predicts which of them can be present. So this file keeps the three genomic landscapes apart
 * (`lungAdenocarcinomaLandscape`, `lungSquamousLandscape`, `lungSmallCellLandscape`) rather than averaging them into
 * one "lung cancer" table, and adds the measurements that decide treatment alongside the genes: PD-L1 by assay and
 * scoring rule with the discordance between assays (`lungPdl1Assays`), tumour mutational burden and why it failed as
 * a selector (`lungTmb`), the never-smoker profile (`lungNeverSmoker`), resistance mechanism by mechanism with what
 * each implies for the next treatment (`lungResistance`), liquid biopsy and reflex testing with what is missed when
 * tissue runs out (`lungLiquidBiopsy`), and the transcriptional subtypes of small-cell disease (`lungSclcSubtypes`).
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 25 September 2026 from the public cBioPortal API (read-only) on the named study id:
 * the count of samples carrying a non-synonymous mutation (or a high-level amplification or deep deletion in the
 * discrete copy-number profile, or a structural variant) over that study's sequenced sample list. They are
 * sample-level frequencies for the study as deposited, not the papers' own percentages, which are quoted alongside
 * where the abstract gives them. Allele shares (EGFR classes, KRAS codons, BRAF V600E against non-V600) are counts of
 * mutation records over all records for that gene in the study, so a tumour with two mutations in one gene counts
 * twice; the EGFR class counts are sample-level and a tumour with both an exon 19 deletion and T790M is counted in
 * both classes, which is the point of reading them separately. Panel cohorts do not see everything: fusions are
 * counted from the structural-variant profile, which needs intron baiting or RNA, so a DNA-panel fusion rate is a
 * floor rather than a measurement, and the whole-exome cohorts (TCGA) undercount them badly. Point mutations in ALK,
 * ROS1, RET and NTRK read high in exome cohorts and are almost all passengers in a smoking-mutated genome: only a
 * fusion is actionable, and the rows say so.
 *
 * Ownership. This layer owns the molecular records: the landscapes, the biomarker readouts and their thresholds, the
 * target prevalence rows and the landscape papers. The cancer records themselves, the glossary terms, the trials and
 * the medicines are owned elsewhere and are only supplemented here.
 */
export const LUNG_CANCER_ID = "nsclc";
const NSCLC = LUNG_CANCER_ID;
const SCLC = "sclc";
const asOf = "2026-09-25";

const doi = (d: string) => `https://doi.org/${d}`;
const pubmed = (pmid: string) => `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
const cbio = (study: string) => `https://www.cbioportal.org/study/summary?id=${study}`;

type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });
/** A partial record for an entity another file owns; arrays append, scalars fill gaps only (see applySpikeSupplements). */
const sup = <T extends EntityInput>(x: { id: string } & Partial<Omit<T, "id" | "kind">>): SpikeSupplement => x as SpikeSupplement;

