// ======================= THE LANDSCAPE TABLES =======================
/**
 * One row per gene or measurement, kept separate by histology because the three diseases share an organ and almost
 * nothing else. `pct` is the headline figure for the prevalence matrix (a number, or a range string like "27-33");
 * `frequency` spells out every cohort behind it. `targetId` is omitted where the corpus has no target record.
 */
export type LungLandscapeRow = {
  gene: string;
  /** Corpus target id (src/data/targets*.ts). */
  targetId?: string;
  alteration: string;
  /** Headline figure for the prevalence matrix: 0 to 100, or a range string. */
  pct: number | string;
  /** Every frequency with its cohort, size and paper. */
  frequency: string;
  /** Comparison between histologies, ancestries, smoking status or assays, when a source makes one. */
  contrast?: string;
  sources: Array<{ label: string; url: string }>;
};

