// ======================= TUMOUR MUTATIONAL BURDEN, AND WHY IT FAILED =======================
export const lungTmb: Array<{ question: string; evidence: string; limit: string; sources: Array<{ label: string; url: string }> }> = [
  { question: "Is mutation load really associated with benefit from checkpoint blockade in lung cancer?",
    evidence: "Yes, and lung cancer is where it was first shown. Whole-exome sequencing of tumours from patients treated with pembrolizumab found higher non-synonymous mutation burden in responders, along with a molecular smoking signature and neoantigen burden that tracked response (Rizvi 2015). Targeted sequencing reproduced it at scale: in 240 patients, panel-based burden correlated with exome-based burden (rho 0.86), burden was higher in the durable-benefit group (p = 0.006), and above the 50th percentile durable benefit was 38.6% against 25.1% below it, with a progression hazard ratio of 1.38 (Rizvi 2018). In 1,552 patients across three centres, increasing burden tracked response, progression-free survival and overall survival within every PD-L1 stratum (Ricciuti 2022).",
    limit: "Association is not a threshold. The same 1,552-patient study needed a regression tree to find its own cut-off and landed on more than 19 mutations per megabase, roughly double the value used in the tumour-agnostic approval, and the two variables interact: response was 57% in tumours with both high burden and PD-L1 50% or more and 8.7% in those with neither (Ricciuti 2022). Burden also correlated with PD-L1 in none of these datasets, so it is a second axis rather than a better version of the first (Rizvi 2018).",
    sources: [link(SRC.rizvi2015), link(SRC.rizvi2018), link(SRC.ricciuti2022tmb)] },
  { question: "Did it work as a trial-defined selector?",
    evidence: "Once. CheckMate 227 enrolled by tumour mutational burden and reported longer progression-free survival with nivolumab plus ipilimumab than chemotherapy in tumours with 10 or more mutations per megabase (Hellmann 2018). In KEYNOTE-042, tissue burden of 175 or more mutations per exome was associated with benefit from pembrolizumab monotherapy over chemotherapy (overall survival hazard ratio 0.62) where burden below that line was not (1.09), and continuous burden tracked outcome on pembrolizumab but not on chemotherapy (Mok 2023).",
    limit: "CheckMate 227 is also the trial that retired the biomarker: the progression-free survival result was reported in the high-burden group, the overall survival benefit that followed did not depend on burden, and the burden endpoint was dropped from the trial (Hellmann 2018). First-line nivolumab selected on PD-L1 alone had already failed outright in CheckMate 026 (progression-free survival 4.2 against 5.9 months, hazard ratio 1.15), a result the exploratory high-burden subgroup could not rescue (Carbone 2017).",
    sources: [link(SRC.checkmate227), link(SRC.mok2023), link(SRC.checkmate026)] },
  { question: "Why did it fail where it matters, in the regimen most patients actually get?",
    evidence: "Because chemo-immunotherapy erases the signal. In KEYNOTE-189 (293 evaluable, non-squamous) and KEYNOTE-407 (312, squamous), continuous tissue burden showed no association with overall survival or progression-free survival for pembrolizumab plus chemotherapy, and none for chemotherapy alone; pembrolizumab combination improved outcomes above and below the 175-mutation cut-off alike, and STK11, KEAP1 and KRAS status made no difference either (Garassino 2023).",
    limit: "That is the decisive negative result. Most patients with driver-negative lung cancer receive chemotherapy with a checkpoint inhibitor, and for that regimen burden selects nobody. It survives as a correlate for single-agent PD-(L)1 blockade only.",
    sources: [link(SRC.garassino2023), link(SRC.mok2023)] },
  { question: "What are the measurement problems underneath the clinical ones?",
    evidence: "The unit is not standardised: 10 mutations per megabase on a targeted panel, 175 mutations per exome on whole-exome sequencing and a blood-based score are three different quantities, and panels differ in gene content, in whether they filter germline variants and in how they treat synonymous changes. Panel estimates track exome estimates well in aggregate (rho 0.86) but with enough scatter around any single cut-off to reclassify patients (Rizvi 2018). Blood-based burden was shown to identify patients who benefit from atezolizumab, and needs its own threshold again (Gandara 2018).",
    limit: "So a tumour mutational burden result in lung cancer says something real about the biology and almost nothing reliable about the decision. The tumour-agnostic approval at 10 or more mutations per megabase was granted on a basket trial with no lung cohort, and no lung-specific companion diagnostic threshold exists; PD-L1 remains the measurement that changes treatment.",
    sources: [link(SRC.rizvi2018), link(SRC.gandara2018), link(SRC.garassino2023)] },
];

// ======================= THE NEVER-SMOKER PROFILE =======================
/**
 * Lung cancer in people who never smoked would be among the ten commonest cancers if it were counted separately.
 * It is a different disease at every level measured: mutation load, driver spectrum, copy-number structure and the
 * timing of the first driver.
 */
export const lungNeverSmoker: Array<{ feature: string; finding: string; implication: string; sources: Array<{ label: string; url: string }> }> = [
  { feature: "Mutation load and signature",
    finding: "High-coverage whole-genome sequencing of 232 lung cancers in never smokers found no strong tobacco smoking signature, even in cases with recorded exposure to secondhand smoke (Zhang 2021). Across 5,243 cancers of smoking-associated types, the signature attributable to misreplication of tobacco carcinogen damage was confined to tissues directly exposed to smoke, and smoking raised mutation burden through several distinct processes at once (Alexandrov 2016). The consequence is visible in the driver table: TP53 is mutated in 36 of 232 never-smoker genomes, 15.5%, against 52 to 54% in the smoker-dominated cohorts (cBioPortal).",
    implication: "Low mutation load is the reason checkpoint blockade works less well in never smokers, and it is also why the disease is so much more likely to have a single clean targetable driver. The two facts are the same fact.",
    sources: [link(SRC.zhang2021), link(SRC.alexandrov2016), CB_NEVER, CB_LUAD_TCGA] },
  { feature: "Driver spectrum",
    finding: "cBioPortal on the never-smoker genomes: EGFR mutated in 66 of 232, 28.4% (exon 19 deletion 38, L858R 20, exon 20 insertion 4); ALK rearrangement in 13, 5.6%; ROS1 in 5; RET in 3; NRG1 in 2; ERBB2 exon 20 insertion in 8, 3.4%; MET exon 14 in 5. KRAS is mutated in only 17, 7.3%, and its allele spectrum is led by G12D rather than G12C. STK11 (5, 2.2%) and KEAP1 (1, 0.4%) are almost absent.",
    implication: "Almost every never-smoker lung cancer has a targetable driver, and it will not be found by a panel that skips fusions. The same list explains why immunotherapy is a poor first choice here: the tumours are cold, and EGFR-mutant and ALK-rearranged disease in particular does badly with checkpoint blockade.",
    sources: [CB_NEVER, link(SRC.zhang2021)] },
  { feature: "Three genomic subtypes defined by copy number",
    finding: "The 232 genomes fell into three classes. Piano, the dominant one and the class that is rare in smokers, carries somatic UBA1 mutations, germline androgen receptor variants and stem-cell-like properties: the lowest mutation burden, the highest intratumour heterogeneity, long telomeres, frequent KRAS mutation and slow growth, with the progenitor cells carrying the first driver dating back many years before diagnosis. Mezzo-forte is defined by specific amplifications and by EGFR mutation, and forte by whole-genome doubling (Zhang 2021).",
    implication: "It is the first evidence that never-smoker lung cancer contains a slow, decades-long lineage as well as a fast one, which matters for screening: a slow-growing piano tumour is exactly the kind a low-dose scan could catch, and exactly the kind a risk model built on pack-years will never select for scanning.",
    sources: [link(SRC.zhang2021)] },
  { feature: "Ancestry is not the same variable as smoking",
    finding: "In 305 East Asian lung adenocarcinomas, EGFR was mutated in 143 of 302 sequenced tumours, 47.4%, against 12.4% in the TCGA series, while KRAS fell to 10.9% and TP53 to 36.1% (cBioPortal luad_oncosg_2020). The same cohort had more stable genomes than European-ancestry cases, with fewer mutations and fewer copy-number alterations, and the difference was larger in smokers than in non-smokers; transcriptomic clustering identified an East Asian subgroup with a simpler genome and upregulated immune genes (Chen 2020).",
    implication: "Ancestry and smoking act separately, and a study that adjusts for one is not adjusting for the other. It also means that a global estimate of how many patients have a targetable driver is meaningless without knowing which population is being described: roughly 30% in the resected Western series, roughly 60% in East Asian adenocarcinoma.",
    sources: [CB_ONCOSG, link(SRC.chen2020)] },
  { feature: "Clinical shorthand that follows from the molecular facts",
    finding: "Never smokers and light smokers are enriched for every fusion class: ROS1-rearranged patients were significantly younger and more often never smokers in a 1,073-patient screen (Bergethon 2012); CD74-NRG1 fusions were discovered in a never-smoker adenocarcinoma series and occur in the invasive mucinous subtype (Fernandez-Cuesta 2014); and MET exon 14 disease, although it sits in older patients, is 36% never smokers (Awad 2016).",
    implication: "Smoking history is a test-ordering instruction, not a diagnosis. A never smoker with lung adenocarcinoma and a negative DNA panel should have an RNA fusion assay before being treated as driver-negative, because that is the population in which a DNA-only work-up is most likely to be wrong.",
    sources: [link(SRC.bergethon2012), link(SRC.fernandezCuesta2014), link(SRC.awad2016), link(SRC.lindeman2018)] },
];

// ======================= RESISTANCE, MECHANISM BY MECHANISM =======================
/**
 * Lung cancer is where acquired resistance is best characterised, because the tumours are rebiopsied and because the
 * inhibitors arrived in generations. Each row names the setting, the mechanism, how often it is found and, most
 * importantly, what it implies for the next treatment.
 */
export const lungResistance: Array<{ setting: string; mechanism: string; frequency: string; nextTreatment: string; sources: Array<{ label: string; url: string }> }> = [
  { setting: "EGFR-mutant disease on a first- or second-generation inhibitor",
    mechanism: "EGFR T790M, the gatekeeper substitution. It was first described in a single patient who relapsed after two years of complete remission on gefitinib, where structural modelling and biochemistry showed the threonine-to-methionine change at position 790 blocked the drug (Kobayashi 2005), and independently in two of five progressing patients whose pretreatment tumours had no such allele (Pao 2005).",
    frequency: "98 of 155 rebiopsied patients, 63%, in the largest prospective rebiopsy series (Yu 2013). cBioPortal records T790M in 91 of 2,653 lung adenocarcinoma samples and 87 of 2,621 non-small-cell samples in the MSK cohorts, which are mostly treated patients resequenced at progression.",
    nextTreatment: "A third-generation inhibitor that binds the mutant cysteine at 797 and spares wild-type EGFR. T790M is the reason rebiopsy at progression became routine and the reason a plasma assay must reach 5% sensitivity to be usable for the call (Lindeman 2018).",
    sources: [link(SRC.kobayashi2005), link(SRC.pao2005), link(SRC.yu2013), link(SRC.lindeman2018)] },
  { setting: "EGFR-mutant disease on osimertinib after T790M",
    mechanism: "EGFR C797S, which removes the cysteine the covalent third-generation inhibitors bind (Thress 2015).",
    frequency: "9 of 41 patients with sequenced tumours at osimertinib resistance, 22%, and it occurred in the 13 of 41, 32%, who kept T790M (Oxnard 2018). cBioPortal records C797S in 19 of 2,653 samples in luad_mskcc_2023_met_organotropism and 20 of 2,621 in nsclc_ctdx_msk_2022.",
    nextTreatment: "It depends on the allele phase, which is the single most consequential sequencing detail in this disease. C797S in trans with T790M can be suppressed by combining a first-generation with a third-generation inhibitor, because each drug covers the allele the other cannot; C797S in cis with T790M defeats both, and the options are a fourth-generation or allosteric inhibitor in a trial, an EGFR-MET bispecific antibody, or chemotherapy. A report that says only that C797S is present has not answered the question.",
    sources: [link(SRC.thress2015), link(SRC.oxnard2018)] },
  { setting: "EGFR-mutant disease, T790M lost at progression",
    mechanism: "A competing, usually pre-existing clone takes over: acquired KRAS mutation, a targetable gene fusion, MET or HER2 amplification, or small-cell transformation.",
    frequency: "28 of 41 patients, 68%, had lost T790M at osimertinib resistance, and losing it was associated with much earlier progression (median time to treatment discontinuation 6.1 against 15.2 months). Serial plasma showed the driver allele fell less steeply in the first weeks of treatment in those patients, so the resistant clone was already there (Oxnard 2018).",
    nextTreatment: "Not another EGFR inhibitor. Loss of T790M means the tumour is no longer EGFR-dependent in the compartment that is growing, so the next step is a full genotype of the progressing lesion, with histology, and treatment aimed at whatever is driving it. The heterogeneity is the point: patients with T790M loss are the strongest argument for biopsying the lesion that is growing rather than the one that is easiest to reach.",
    sources: [link(SRC.oxnard2018), link(SRC.tracerx2017)] },
  { setting: "EGFR-mutant disease, bypass through a second receptor",
    mechanism: "MET amplification, which restores PI3K signalling through ERBB3 rather than through EGFR, so the EGFR inhibitor is still working and the pathway is on anyway (Engelman 2007). HER2 amplification does the same job by a different receptor.",
    frequency: "MET amplification was found in 4 of 18 gefitinib- or erlotinib-resistant specimens, 22%, in the discovery series (Engelman 2007), and in 4 of 75 rebiopsied patients, 5%, in the larger prospective series, where HER2 amplification was 3 of 24, 13% (Yu 2013). It is commoner after osimertinib than after the earlier inhibitors.",
    nextTreatment: "Add a MET inhibitor to the EGFR inhibitor rather than replacing it, because the tumour still needs EGFR blocked. This is the mechanism the EGFR-MET bispecific antibodies were designed around, and it is the reason a resistance panel must report copy number and not only mutations.",
    sources: [link(SRC.engelman2007), link(SRC.yu2013)] },
  { setting: "EGFR-mutant disease, histological transformation to small-cell carcinoma",
    mechanism: "Lineage plasticity rather than a new mutation in the pathway. The transformed tumour keeps the founder EGFR mutation and switches to a neuroendocrine programme, which requires both RB1 and TP53 to be gone.",
    frequency: "5 of 37 patients rebiopsied at resistance, 14%, in the first systematic series (Sequist 2011) and 4 of 155, 3%, in the larger one (Yu 2013). In a multi-institution series of 67 transformed cases the median time from diagnosis to transformation was 17.8 months and median survival after transformation 10.9 months; all kept the founder EGFR mutation and 15 of 19 previously T790M-positive cases were T790 wild-type at transformation (Marcoux 2019).",
    nextTreatment: "Platinum and etoposide, which produce high response rates, and taxanes after that; checkpoint inhibitors do not work, with no responses in 17 treated patients (Marcoux 2019). The prediction is available before the event: complete inactivation of both RB1 and p53 in the original adenocarcinoma was present in 82% of transformed cases against 3% of non-transformed ones (odds ratio 131), giving a 43-fold higher risk of transformation (Lee 2017), and in a separate cohort the EGFR, RB1 and TP53 triple-mutant group was 5% of EGFR-mutant lung cancers but supplied 18% of transformations, with whole-genome doubling and APOBEC hypermutation enriched in the ones that transformed (Offin 2019). A triple-mutant result therefore changes the surveillance plan and lowers the threshold for rebiopsy.",
    sources: [link(SRC.sequist2011), link(SRC.yu2013), link(SRC.marcoux2019), link(SRC.lee2017), link(SRC.offin2019)] },
  { setting: "ALK-rearranged disease on crizotinib (first generation)",
    mechanism: "Secondary ALK kinase-domain mutations, but only in a minority: crizotinib is a weak ALK inhibitor and most tumours escape simply by signalling through incompletely inhibited ALK.",
    frequency: "Across 103 repeat biopsies, each inhibitor was associated with its own spectrum of resistance mutations; after crizotinib the mutations were diverse (L1196M, G1269A and others) and present in roughly a fifth of cases (Gainor 2016).",
    nextTreatment: "A second-generation inhibitor, which works whether or not a resistance mutation is present, because the usual problem was potency rather than a changed drug pocket (Gainor 2016).",
    sources: [link(SRC.gainor2016)] },
  { setting: "ALK-rearranged disease on a second-generation inhibitor (alectinib, brigatinib, ceritinib)",
    mechanism: "ALK resistance mutations, now the dominant mechanism and now concentrated on one residue: G1202R, at the solvent front, rose significantly in frequency after second-generation treatment (Gainor 2016).",
    frequency: "About a quarter of the 198 patients in the lorlatinib registration study had an ALK mutation detectable in plasma or tissue at baseline; among those who had failed one or more second-generation inhibitors, the mutation-positive group was the group that responded (Shaw 2019).",
    nextTreatment: "Lorlatinib, and the decision turns on the genotype. After one or more second-generation inhibitors, objective response was 69% with an ALK mutation on tissue genotyping against 27% without, and median progression-free survival 11.0 against 5.4 months (hazard ratio 0.47); after crizotinib alone, mutation status made no difference (Shaw 2019). In the ceritinib-resistant patient-derived cell lines, the presence of an ALK mutation predicted lorlatinib sensitivity and its absence predicted resistance (Gainor 2016). So a patient progressing on a second-generation inhibitor with no ALK mutation is ALK-independent and is better served by chemotherapy or a trial than by a third-generation inhibitor.",
    sources: [link(SRC.shaw2019), link(SRC.gainor2016)] },
  { setting: "ALK-rearranged disease on lorlatinib (third generation)",
    mechanism: "Compound mutations, two ALK changes on the same allele.",
    frequency: "Described first in a single patient whose tumour acquired C1156Y on crizotinib, failed a second-generation inhibitor, responded to lorlatinib, and then relapsed with L1198F added to C1156Y (Shaw 2016).",
    nextTreatment: "Sometimes the drug the patient has already failed. L1198F blocks lorlatinib sterically but paradoxically improves crizotinib binding and cancels the effect of C1156Y, and rechallenge with crizotinib resolved that patient's symptoms and liver failure (Shaw 2016). It is a single case and it is the cleanest demonstration in oncology that resistance is a property of a drug-protein pair rather than a property of the tumour, and that sequencing at every progression can reopen options that look closed.",
    sources: [link(SRC.shaw2016)] },
  { setting: "Any oncogene-addicted disease: the shape of the problem",
    mechanism: "Pre-existing subclones rather than newly created mutations. Multiregion sequencing of the first 100 TRACERx patients showed extensive intratumour heterogeneity, with driver events distributed unevenly between regions of the same tumour, so a single biopsy is a sample rather than a census (Jamal-Hanjani 2017).",
    frequency: "Heterogeneity is the rule rather than a subgroup finding, and in EGFR-mutant disease the kinetics of the driver allele in plasma over the first three weeks of treatment already separate the patients whose resistant clone was there from the start (Oxnard 2018).",
    nextTreatment: "It argues for genotyping at every progression rather than once at diagnosis, for biopsying the growing lesion, and for reading plasma and tissue together, since plasma samples every lesion at once and tissue samples one of them properly.",
    sources: [link(SRC.tracerx2017), link(SRC.oxnard2018)] },
];

// ======================= LIQUID BIOPSY AND REFLEX TESTING =======================
export const lungLiquidBiopsy: Array<{ question: string; evidence: string; limit: string; sources: Array<{ label: string; url: string }> }> = [
  { question: "Can plasma sequencing replace tissue genotyping at diagnosis?",
    evidence: "It matches it and is faster. In 282 patients with newly diagnosed metastatic non-small-cell lung cancer, physician-choice tissue genotyping found a guideline-recommended biomarker in 60 patients, 21.3%, and comprehensive cell-free DNA found one in 77, 27.3%, meeting non-inferiority; concordance for the alterations with approved drugs exceeded 98% with 100% positive predictive value against tissue for the 34 EGFR, ALK and BRAF positives; adding plasma to tissue raised the number of patients with a biomarker by 48%, from 60 to 89; and median turnaround was 9 days against 15 (Leighl 2019). In a separate 323-patient cohort, plasma alone found a targetable alteration in 31 of 94 patients, 33%, sparing an invasive biopsy, and adding plasma to tissue raised detection from 47 of 229 to 82 of 229, 20.5% to 35.8%, with 36 of 42 patients treated on a plasma result responding or remaining stable (Aggarwal 2019).",
    limit: "The guideline position is asymmetric and correct: plasma can rule a mutation in but cannot rule one out, so a negative plasma result in a patient who could have a driver has to be followed by tissue (Lindeman 2018).",
    sources: [link(SRC.leighl2019), link(SRC.aggarwal2019), link(SRC.lindeman2018)] },
  { question: "What does a negative plasma result actually mean?",
    evidence: "It means the tumour did not shed enough DNA into the blood to be seen, which is as much a fact about the disease as about the assay. Tumour fraction falls with low volume, with disease confined to the chest and above all with disease confined to the brain, where the blood-brain barrier keeps circulating tumour DNA out of the plasma. The clinical sensitivity of a comprehensive plasma panel for any guideline biomarker was 80% against tissue in the prospective comparison (Leighl 2019).",
    limit: "So one in five biomarker-positive patients is missed by plasma alone. The failure is not random: it concentrates in exactly the patients whose tumours are hardest to biopsy.",
    sources: [link(SRC.leighl2019), link(SRC.aggarwal2019)] },
  { question: "What is missed when the tissue sample is too small, even with a good panel?",
    evidence: "Four different things, each with its own fix. Fusions in ALK, ROS1, RET, NTRK and NRG1 need RNA sequencing or a DNA panel that baits the breakpoint introns; a coding-exon panel reports wild-type. MET exon 14 skipping is the same problem in a different gene, since the alterations sit in the flanking introns (Frampton 2015, Awad 2016). PD-L1 cannot be measured in plasma at all, so a plasma-only work-up leaves the immunotherapy decision unmade and needs a stained slide from somewhere. And histology itself, the thing that tells adenocarcinoma from squamous carcinoma from small-cell carcinoma and that decides which of the alterations above are worth looking for, is a tissue question with no liquid substitute.",
    limit: "The guideline consequence is a tissue-stewardship rule rather than a testing rule: cut the unstained slides at the time of diagnosis, stop reflex immunohistochemistry panels that consume the block, and use cytology cell blocks, which score PD-L1 reproducibly (intraclass correlation 0.78 to 0.85) and are acceptable substrates for molecular testing (Tsao 2018, Lindeman 2018).",
    sources: [link(SRC.frampton2015), link(SRC.awad2016), link(SRC.tsao2018), link(SRC.lindeman2018)] },
  { question: "What does the current testing guideline actually require?",
    evidence: "Eighteen new recommendations in the 2018 update. ROS1 testing for every patient with adenocarcinoma; ERBB2, MET, BRAF, KRAS and RET included for laboratories running next-generation sequencing panels; cytology samples acceptable; immunohistochemistry acceptable as an alternative to fluorescence in situ hybridisation for ALK and ROS1 screening; immunohistochemistry explicitly not acceptable for EGFR; assays for EGFR T790M in acquired resistance must reach 5% sensitivity; and cell-free DNA may be used to rule a targetable mutation in when tissue is limited or hard to obtain (Lindeman 2018).",
    limit: "The guideline predates the licensed indications for MET exon 14, RET fusion, KRAS G12C, HER2 exon 20 insertion and NTRK fusion becoming routine, so in practice the panel has to be broader than the guideline text, and the practical question has shifted from which genes to test to whether the tissue survives the testing.",
    sources: [link(SRC.lindeman2018)] },
  { question: "What else does plasma do once treatment starts?",
    evidence: "It tracks resistance in real time. Serial plasma genotyping after osimertinib resistance reproduced the tissue findings in a 110-patient validation cohort and showed that patients who lost T790M had a shallower fall in driver allele fraction in the first one to three weeks of treatment (100% against 83% decrease), which is a two-week readout of an outcome that otherwise takes a year to declare (Oxnard 2018). Plasma genotyping also identified the ALK resistance mutations that predict lorlatinib benefit, although tissue genotyping separated the groups more sharply (Shaw 2019).",
    limit: "Plasma is the better sampler and tissue is the better assay: plasma sees every lesion at low depth and tissue sees one lesion completely, and the difference showed up directly in the lorlatinib analysis, where the progression-free survival split by ALK mutation status was significant on tissue (11.0 against 5.4 months) and not on plasma (7.3 against 5.5 months).",
    sources: [link(SRC.oxnard2018), link(SRC.shaw2019)] },
];

