// ======================= SUPPLEMENTS =======================
/** Landscape rows grouped by the cancer record their prevalence belongs to. */
const landscapeByCancer: Array<[string, LungLandscapeRow[]]> = [
  [NSCLC, [...lungAdenocarcinomaLandscape, ...lungSquamousLandscape]],
  [SCLC, lungSmallCellLandscape],
];

/** Target supplements derived from the landscape tables: a prevalence row per (gene, alteration, histology). */
const targetSupplements: SpikeSupplement[] = (() => {
  const byTarget = new Map<string, Array<{ cancerId: string; row: LungLandscapeRow }>>();
  for (const [cancerId, rows] of landscapeByCancer) for (const r of rows) if (r.targetId) byTarget.set(r.targetId, [...(byTarget.get(r.targetId) ?? []), { cancerId, row: r }]);
  return [...byTarget.entries()].map(([targetId, entries]) => sup<TargetInput>({
    id: targetId,
    cancers: [...new Set(entries.map((e) => e.cancerId))],
    prevalence: entries.map(({ cancerId, row }) => ({ cancerId, pct: row.pct, measure: row.alteration, source: row.sources[0].url, note: row.frequency })),
    whereFound: entries.map(({ cancerId, row }) => `${cancerId === SCLC ? "Small-cell lung cancer" : "Non-small-cell lung cancer"}: ${row.alteration.toLowerCase()} ${typeof row.pct === "number" ? `about ${row.pct}%` : `${row.pct}%`}`),
    keyPapers: [...new Set(entries.flatMap(({ row }) => row.sources.map((s) => PAPER_BY_URL.get(s.url)).filter((x): x is string => !!x)))],
  }));
})();

/** Target ids with a non-small-cell prevalence row, for the cancer patch. */
const nsclcTargetIds = [...new Set([...lungAdenocarcinomaLandscape, ...lungSquamousLandscape].map((r) => r.targetId).filter((x): x is string => !!x))];
const sclcTargetIds = [...new Set(lungSmallCellLandscape.map((r) => r.targetId).filter((x): x is string => !!x))];

